public partial struct Bounds2f : IEquatable<Bounds2f>
{
    // Bounds2 Public Members
    public Point2f pMin, pMax;

    // Bounds2 Public Methods
    // NOTE: new Bounds2f() is empty (pMin > pMax) like pbrt's default constructor,
    // but default(Bounds2f) is the degenerate box at the origin.
    public Bounds2f()
    {
        Float minNum = Float.MinValue;
        Float maxNum = Float.MaxValue;
        pMin = new Point2f(maxNum, maxNum);
        pMax = new Point2f(minNum, minNum);
    }

    public Bounds2f(Point2f p)
    {
        pMin = pMax = p;
    }

    public Bounds2f(Point2f p1, Point2f p2)
    {
        pMin = Min(p1, p2);
        pMax = Max(p1, p2);
    }

    public Bounds2f(Bounds2i b)
    {
        if (b.IsEmpty())
            // Be careful about overflowing float->int conversions and the
            // like.
            this = new Bounds2f();
        else
        {
            pMin = new Point2f(b.pMin);
            pMax = new Point2f(b.pMax);
        }
    }

    public Point2f this[int i]
    {
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        readonly get
        {
            DCHECK(i == 0 || i == 1);
            return (i == 0) ? pMin : pMax;
        }
        set
        {
            DCHECK(i == 0 || i == 1);
            if (i == 0) pMin = value; else pMax = value;
        }
    }

    public readonly Point2f Corner(int corner)
    {
        DCHECK(corner >= 0 && corner < 4);
        return new Point2f(this[corner & 1].x, this[(corner & 2) != 0 ? 1 : 0].y);
    }

    public readonly Vector2f Diagonal() => pMax - pMin;

    public readonly Float Area()
    {
        Vector2f d = pMax - pMin;
        return d.x * d.y;
    }

    public readonly int MaxDimension()
    {
        Vector2f diag = Diagonal();
        if (diag.x > diag.y)
            return 0;
        else
            return 1;
    }

    public readonly bool IsEmpty() => pMin.x >= pMax.x || pMin.y >= pMax.y;
    public readonly bool IsDegenerate() => pMin.x > pMax.x || pMin.y > pMax.y;

    public static bool operator ==(Bounds2f a, Bounds2f b) => a.pMin == b.pMin && a.pMax == b.pMax;
    public static bool operator !=(Bounds2f a, Bounds2f b) => !(a == b);
    public readonly bool Equals(Bounds2f other) => this == other;
    public override readonly bool Equals(object? obj) => obj is Bounds2f other && this == other;
    public override readonly int GetHashCode() => HashCode.Combine(pMin, pMax);
    public override readonly string ToString() => $"[ {pMin} - {pMax} ]";
}

